style.css:
@-moz-document domain("code.ptit.edu.vn") {
body {
        background-image: url('https://png.pngtree.com/background/20230517/original/pngtree-female-anime-character-sitting-under-a-pink-flowering-tree-picture-image_2640410.jpg'); /* Thay bằng link ảnh của bạn */
        background-size: cover;
        background-attachment: fixed;
        background-position: center;
        filter: brightness(0.8);
    }

    #header, .navbar, .footer {
        background: rgba(0, 0, 0, 0.7) !important; /* Làm thanh menu trong suốt */
    }

    .container {
        background: rgba(225, 225, 225, 0.1) !important; /* Làm mờ nền nội dung */
        backdrop-filter: blur(5px); /* Hiệu ứng làm mờ */
        border-radius: 10px;
        padding: 15px;
    }
}
